<script setup>
import { useForm, Link, router } from '@inertiajs/vue3';
const props = defineProps({ course:Object, role:String });
const create = useForm({ title:'', description:'' });
const add = () => create.post(`/${props.role}/courses/${props.course.id}/sections`, { onSuccess:()=>create.reset() });
const rename = section => { const title=window.prompt('عنوان جدید فصل', section.title); if(title?.trim()) router.put(`/${props.role}/courses/${props.course.id}/sections/${section.id}`, {title, description:section.description}); };
</script>
<template><section class="rounded-2xl border bg-white p-5">
<div class="mb-4 flex flex-wrap justify-between gap-2"><h2 class="text-lg font-bold">ساختار دوره</h2><Link :href="`/${role}/courses/${course.id}/lessons/create`" class="rounded-xl bg-teal-700 px-4 py-2 text-white">درس جدید</Link></div>
<form class="mb-5 flex flex-wrap gap-2" @submit.prevent="add"><input v-model="create.title" placeholder="عنوان فصل" class="max-w-sm"><button class="rounded-xl border px-4 py-2">افزودن فصل</button><p class="w-full text-sm text-red-600">{{create.errors.title}}</p></form>
<div class="mb-5 space-y-2"><div v-for="section in course.sections" :key="section.id" class="flex flex-wrap items-center justify-between rounded-xl bg-slate-50 p-3"><div><strong>{{section.title}}</strong><span v-if="section.deleted_at" class="mr-2 text-xs text-red-700">بایگانی‌شده</span></div><div class="flex gap-3"><template v-if="!section.deleted_at"><button type="button" class="text-teal-700" @click="rename(section)">ویرایش</button><Link :href="`/${role}/courses/${course.id}/sections/${section.id}/move/up`" method="post" as="button">↑</Link><Link :href="`/${role}/courses/${course.id}/sections/${section.id}/move/down`" method="post" as="button">↓</Link><Link :href="`/${role}/courses/${course.id}/sections/${section.id}`" method="delete" as="button" class="text-red-700">بایگانی</Link></template><Link v-else-if="role==='admin'" :href="`/admin/courses/${course.id}/sections/${section.id}/restore`" method="post" as="button" class="text-teal-700">بازیابی</Link></div></div></div>
<div class="space-y-2"><div v-for="lesson in course.lessons" :key="lesson.id" class="flex flex-wrap items-center justify-between rounded-xl border p-3" :class="lesson.deleted_at?'opacity-60':''"><div><strong>{{lesson.sort_order}}. {{lesson.title}}</strong><p class="text-xs text-slate-500">{{lesson.section?.title||'بدون فصل'}} — {{lesson.status}}</p></div><div v-if="!lesson.deleted_at" class="flex gap-2"><Link :href="`/${role}/courses/${course.id}/lessons/${lesson.id}/edit`" class="text-teal-700">ویرایش</Link><Link :href="`/${role}/courses/${course.id}/lessons/${lesson.id}/move/up`" method="post" as="button">↑</Link><Link :href="`/${role}/courses/${course.id}/lessons/${lesson.id}/move/down`" method="post" as="button">↓</Link><Link :href="`/${role}/courses/${course.id}/lessons/${lesson.id}`" method="delete" as="button" class="text-red-700">بایگانی</Link></div></div></div>
</section></template>
